import java.util.*;
import java.io.*;
import java.math.*;

public class E {
    static final long MOD_CONST = 998244353L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long N = Long.parseLong(st.nextToken());
        long M = Long.parseLong(st.nextToken());
        long L = Long.parseLong(st.nextToken());
        long R = Long.parseLong(st.nextToken());

        long total = N * M;
        BigInteger totalPower = BigInteger.valueOf(total);
        BigInteger rangeCount = BigInteger.valueOf(R - L + 1);
        BigInteger modBig = BigInteger.valueOf(MOD_CONST);

        if ((N * M) % 2 == 1) {
            long answer = rangeCount.modPow(totalPower, modBig).longValue();
            System.out.println((answer + MOD_CONST) % MOD_CONST);
        } else {
            long answer = rangeCount.modPow(totalPower, modBig).longValue();
            if ((R - L) % 2 == 0) {
                answer++;
            }
            long invTwo = power(2, MOD_CONST - 2, MOD_CONST);
            answer = (answer * invTwo) % MOD_CONST;
            System.out.println(answer);
        }
    }

    public static long power(long base, long exp, long mod) {
        long res = 1L;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                res = (res * base) % mod;
            }
            exp >>= 1;
            base = (base * base) % mod;
        }
        return res;
    }
}
